      }), " Horizontal scaling only works if any server instance can handle any request. Every piece of state held on a server instance is a constraint on your ability to scale, deploy, and recover from failure. Audit your server code for local state and move it out."]
    }), "\n", _jsxs(_components.p, {
      children: [_jsx(_components.strong, {
